def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_aggressive = 0
    urgent_opps = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 3:
                prev = opp.get('previous_trace', {}) or {}
                pb = prev.get('bid')
                if pb is not None and pb >= DAILY_SALARY * 0.9:
                    rich_aggressive += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opps += 1
            prev = opp.get('previous_trace', {}) or {}
            pb = prev.get('bid')
            if pb is not None:
                prev_bids.append(float(pb))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.25))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = 0
    if hp <= 2 or no_water >= 2:
        my_urgent = 3
    elif hp <= 4 or no_water >= 1:
        my_urgent = 2
    elif hp <= 6:
        my_urgent = 1

    base = DAILY_SALARY * (0.26 + 0.18 * scarcity)

    if my_urgent == 0:
        if max_prev >= DAILY_SALARY * 1.2:
            bid = DAILY_SALARY * 0.22
        elif max_prev >= DAILY_SALARY * 0.95:
            bid = DAILY_SALARY * 0.28
        else:
            bid = max(base, min(DAILY_SALARY * 0.52, avg_prev + 2.0 if avg_prev > 0 else DAILY_SALARY * 0.35))
    elif my_urgent == 1:
        target = max(DAILY_SALARY * 0.58, avg_prev + 5.0 if avg_prev > 0 else DAILY_SALARY * 0.6)
        bid = target + DAILY_SALARY * 0.08 * scarcity
    elif my_urgent == 2:
        target = max(DAILY_SALARY * 0.82, max_prev + 3.0 if max_prev > 0 else DAILY_SALARY * 0.85)
        bid = target + DAILY_SALARY * 0.08 * scarcity
    else:
        target = max(DAILY_SALARY * 0.96, max_prev + 6.0 if max_prev > 0 else DAILY_SALARY)
        bid = target + DAILY_SALARY * 0.1 * scarcity

    if rich_aggressive >= 2 and my_urgent == 0:
        bid *= 0.82
    if urgent_opps >= 2 and my_urgent >= 1:
        bid += 6.0

    days_left = max(1, 10 - day + 1)
    reserve_floor = DAILY_SALARY * 0.35 * max(0, days_left - 1)
    max_today = budget - reserve_floor
    if my_urgent >= 2:
        max_today = budget
    elif my_urgent == 1:
        max_today = max(budget * 0.55, budget - reserve_floor)

    if max_today < 0:
        max_today = budget * 0.25

    bid = min(bid, budget, max_today)

    if my_urgent == 0:
        bid = max(0.0, bid)
    elif my_urgent == 1:
        bid = max(bid, DAILY_SALARY * 0.5)
    elif my_urgent == 2:
        bid = max(bid, DAILY_SALARY * 0.78)
    else:
        bid = max(bid, DAILY_SALARY * 0.92)

    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))
